-- Constellation 4: Girişimcilik · "Roket"

                     difficulty, duration_min, xp_reward, star_x, star_y, sort_order) VALUES
(14, 'fikirden-urune', 4, $$Fikirden Ürüne: Girişimciliğe Giriş$$,
 $$İyi bir girişimin çözümle değil problemle başladığını; müşteriyi tanımanın ve doğrulamanın önemini öğren.$$,
 ARRAY[$$Problem ile çözümü ayırt etmek$$, $$Hedef müşteri kitlesini tanımlamak$$,
       $$Müşteri görüşmeleriyle fikri doğrulamak$$, $$Değer önerisini tek cümleyle ifade etmek$$],
 ARRAY[$$Başarılı girişimlerin çoğu parlak bir çözümle değil, gerçek ve can yakan bir problemle başlar. Kendine sorman gereken ilk soru şudur: Bu problemi kim, ne sıklıkla ve ne kadar şiddetli yaşıyor?$$,
       $$Fikrini doğrulamanın en ucuz yolu potansiyel müşterilerle konuşmaktır. Onlara fikrini satmaya çalışma; problemi nasıl yaşadıklarını ve bugün nasıl çözdüklerini dinle. İnsanların ne dediği değil, ne yaptığı daha çok şey anlatır.$$,
       $$Değer önerisi, ürününün kime, hangi problemi, nasıl çözdüğünü tek cümlede anlatır. Örneğin: "SkillHub, dijital beceri öğrenmek isteyen gençlere ilerlemelerini bir gece gökyüzü gibi görünür kılarak motivasyon sağlar."$$],
 NULL, 'BEGINNER', 25, 100, 610, 470, 1),
(15, 'lean-startup-ve-mvp', 4, $$Lean Startup ve MVP$$,
 $$Kur-Ölç-Öğren döngüsüyle en küçük işe yarar ürünü çıkar, veriye göre pivot ya da devam kararı ver.$$,
 ARRAY[$$Kur-Ölç-Öğren döngüsünü uygulamak$$, $$Bir MVP'nin kapsamını belirlemek$$,
       $$Gösteriş metrikleriyle eyleme dönük metrikleri ayırt etmek$$, $$Pivot kararının ne zaman gerektiğini anlamak$$],
 ARRAY[$$Lean Startup yaklaşımı, belirsizlik altında ürün geliştirmeyi bir öğrenme süreci olarak görür. Kur-Ölç-Öğren döngüsünde amaç, en kısa sürede gerçek kullanıcıdan geri bildirim almaktır.$$,
       $$MVP (Minimum Viable Product), en kritik varsayımını test etmeni sağlayan en küçük üründür. Bir gecede çıkarılan bir yarışma prototipi de aslında bir MVP'dir: Fikrin işe yarayıp yaramadığını hızlıca gösterir.$$,
       $$Ölçerken gösteriş metriklerine (toplam indirme gibi) değil, eyleme dönük metriklere (haftalık aktif kullanıcı, tekrar kullanım oranı gibi) bak. Veriler varsayımını çürütüyorsa stratejiyi değiştirmek (pivot) başarısızlık değil, öğrenmenin sonucudur.$$],
 'fEvKo90qBns', 'INTERMEDIATE', 35, 150, 720, 380, 2),
(16, 'is-modeli-kanvasi', 4, $$İş Modeli Kanvası$$,
 $$Dokuz yapı taşıyla bir işin nasıl değer ürettiğini, sunduğunu ve para kazandığını tek sayfada gör.$$,
 ARRAY[$$Kanvasın dokuz yapı taşını tanımak$$, $$Müşteri segmentleri ile değer önerisini eşleştirmek$$,
       $$Gelir modellerini karşılaştırmak$$, $$Maliyet yapısını ve kilit ortaklıkları belirlemek$$],
 ARRAY[$$İş Modeli Kanvası, bir işin tüm mantığını tek sayfada gösteren görsel bir araçtır. Dokuz yapı taşından oluşur: Müşteri segmentleri, değer önerisi, kanallar, müşteri ilişkileri, gelir akışları, kilit kaynaklar, kilit aktiviteler, kilit ortaklıklar ve maliyet yapısı.$$,
       $$Kanvasın kalbinde değer önerisi ile müşteri segmentlerinin uyumu vardır. Kime hizmet ettiğini bilmeden neyi sunacağını, hangi kanaldan ulaşacağını ya da nasıl para kazanacağını doğru belirleyemezsin.$$,
       $$Gelir akışları abonelik, tek seferlik satış, reklam veya freemium gibi modellerden oluşabilir. Kanvas bir kez doldurulup unutulan bir belge değildir; her müşteri görüşmesi ve deneyle güncellenen yaşayan bir taslaktır.$$],
 'QoAOzMTLP5s', 'INTERMEDIATE', 30, 150, 730, 540, 3),
(17, 'pitch-sanati', 4, $$Pitch: Fikrini Anlatma Sanatı$$,
 $$Problemi, çözümü ve ekibi birkaç dakikada akılda kalıcı bir hikâyeye dönüştür; jüriyi ikna et.$$,
 ARRAY[$$Etkili bir pitch'in yapısını kurmak$$, $$Problemi bir hikâyeyle anlatmak$$,
       $$Demo ile çözümü somutlaştırmak$$, $$Zor sorulara hazırlıklı olmak$$],
 ARRAY[$$Pitch, fikrini kısa sürede net ve ikna edici şekilde anlatma sanatıdır. Klasik bir yapı şöyledir: Problem, çözüm, demo, pazar, iş modeli, ekip ve talep (ne istiyorsun?).$$,
       $$İnsanlar rakamları değil hikâyeleri hatırlar. Problemi yaşayan gerçek bir kişinin hikâyesiyle başlamak dinleyiciyi hemen içine çeker. Ardından canlı bir demo, çözümünün çalıştığını tüm slaytlardan daha iyi kanıtlar.$$,
       $$Code Night gibi yarışmalarda jüri birkaç dakika içinde karar verir; bu yüzden prova etmek şarttır. Olası sorulara (rakipler, ölçeklenme, iş modeli) önceden cevap hazırlamak sahnedeki özgüvenini ikiye katlar.$$],
 '17XZGUX_9iM', 'ADVANCED', 30, 200, 870, 460, 4);



