INSERT INTO questions (id, lesson_id, position, prompt, explanation) VALUES
(141, 14, 1, $$Başarılı bir girişim fikri genellikle neyle başlar?$$, $$Kalıcı girişimler, çözmeye değer gerçek bir problemle başlar.$$),
(142, 14, 2, $$Fikri doğrulamanın en ucuz ve hızlı yolu hangisidir?$$, $$Müşteri görüşmeleri, kod yazmadan önce problemin gerçek olup olmadığını gösterir.$$),
(143, 14, 3, $$Değer önerisi neyi anlatır?$$, $$Değer önerisi; hedef müşteriyi, problemi ve çözümü net bir cümlede birleştirir.$$),
(144, 14, 4, $$Müşteri görüşmelerinde en değerli bilgi genellikle hangisidir?$$, $$İnsanların geçmişteki davranışları, gelecekle ilgili iyi niyetli tahminlerinden daha güvenilirdir.$$),
(151, 15, 1, $$Lean Startup'taki temel döngü hangisidir?$$, $$Kur-Ölç-Öğren döngüsü, hızlı deneylerle doğrulanmış öğrenmeyi hedefler.$$),
(152, 15, 2, $$MVP'nin temel amacı nedir?$$, $$MVP, öğrenmeyi en hızlı sağlayacak en küçük üründür.$$),
(153, 15, 3, $$Aşağıdakilerden hangisi eyleme dönük (actionable) bir metriktir?$$, $$Tekrar kullanım oranı, ürünün gerçek değer üretip üretmediğini gösterir ve karar almaya yardım eder.$$),
(154, 15, 4, $$Veriler temel varsayımını çürüttüğünde stratejiyi değiştirmeye ne denir?$$, $$Pivot, öğrendiklerine göre ürünün yönünü değiştirmektir.$$),
(161, 16, 1, $$İş Modeli Kanvası kaç yapı taşından oluşur?$$, $$Kanvas dokuz yapı taşından oluşur.$$),
(162, 16, 2, $$Kanvasın merkezinde hangi yapı taşı yer alır?$$, $$Değer önerisi kanvasın merkezindedir ve müşteri segmentleriyle uyumlu olmalıdır.$$),
(163, 16, 3, $$Temel özelliklerin ücretsiz, gelişmiş özelliklerin ücretli olduğu gelir modeli hangisidir?$$, $$Freemium modelinde ürünün temel hâli ücretsizdir; gelir, ücretli premium özelliklerden gelir.$$),
(164, 16, 4, $$İş Modeli Kanvası için hangisi doğrudur?$$, $$Kanvas, öğrendikçe güncellenen yaşayan bir çalışma aracıdır.$$),
(171, 17, 1, $$Etkili bir pitch genellikle neyle başlamalıdır?$$, $$Dinleyici önce problemin önemini anlamalı; çözüm ancak o zaman anlam kazanır.$$),
(172, 17, 2, $$Çözümün çalıştığını en ikna edici şekilde ne gösterir?$$, $$Canlı demo, ürünün gerçekten çalıştığını somut olarak kanıtlar.$$),
(173, 17, 3, $$Bir pitch'teki "talep" (ask) bölümü neyi ifade eder?$$, $$Talep bölümünde, sunumun sonunda dinleyiciden somut olarak ne istediğini söylersin.$$),
(174, 17, 4, $$Pitch öncesi hazırlıkta hangisi en çok fayda sağlar?$$, $$Prova ve soru hazırlığı, kısa sürede net ve özgüvenli bir sunum yapmanı sağlar.$$);
